(() => {
  'use strict';
  const $ = (s,root=document)=>root.querySelector(s);
  const categories=window.FLOWER_CATEGORIES,products=window.FLOWER_PRODUCTS;
  const safe=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const priceLabel=p=>p.price===null?'Цена по запросу':p.price.toLocaleString('ru-RU')+' ₽';
  const stockNote='Наличие, размеры растения, актуальную стоимость и другие детали уточняйте в личных сообщениях в MAX или Одноклассниках.';
  const escapePattern=s=>String(s).replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
  function productDescription(p){
    const compact=s=>String(s??'').replace(/\s+/g,' ').trim();
    let text=compact(p.description);
    if(p.sku)text=text.replace(new RegExp('^'+escapePattern(p.sku)+'(?![0-9/])\\s*','iu'),'');
    const name=compact(p.name),plant=categories.find(c=>c.id===p.category)?.plant||'';
    const names=[name,plant?name.replace(new RegExp('^(?:вегетативн[а-яё]+\\s+)?'+escapePattern(plant)+'\\s+','iu'),''):name];
    for(const candidate of names){
      if(!candidate)continue;
      const prefix=new RegExp('^'+escapePattern(candidate)+'(?=$|[\\s.,;:()—–-])','iu');
      if(prefix.test(text)){text=text.replace(prefix,'');break;}
    }
    text=text.replace(/\d+(?:[.,]\d+)?\s*(?:руб(?:лей|ля|ль)?\.?|р\.?|₽)(?=\s|[),.;]|$)/giu,'');
    const trim=s=>s.replace(/^[\s,.;:—–-]+|[\s,;:—–-]+$/gu,'').trim();
    text=trim(text);
    if(text.startsWith('(')&&text.endsWith(')'))text=trim(text.slice(1,-1));
    if(!text)text=compact(p.size);
    text=text.replace(/укорененн/giu,m=>m[0]==='У'?'Укоренённ':'укоренённ')
      .replace(/(\d+)\s*гр(?=\s|[.,;:]|$)/giu,'$1 г')
      .replace(/\s+([,.;:!?])/g,'$1').replace(/([;:])(?=\S)/g,'$1 ').replace(/,(?=[^\s\d])/g,', ')
      .replace(/([.!?)])(?=[А-Яа-яЁё])/gu,'$1 ').replace(/\(\s+/g,'(').replace(/\s+\)/g,')');
    text=compact(text).replace(/(в\s+\d+\s*г\s+)стаканчики/giu,'$1стаканчике');
    if(/^\d+\s*г\s+стаканч/iu.test(text))text='В '+text;
    if(text)text=text[0].toLocaleUpperCase('ru-RU')+text.slice(1)+(/[.!?…]$/.test(text)?'':'.');
    return text;
  }
  const key='nadezhda-favorites-v1';
  let saved;
  try { const raw=JSON.parse(localStorage.getItem(key)||'[]'); saved=new Set(Array.isArray(raw)?raw.filter(id=>products.some(p=>p.id===id)):[]); } catch { saved=new Set(); }
  const icon=(name)=>`<img class="icon" src="./assets/${name}.svg?v=b1399a3d11d3" alt="" width="22" height="22">`;
  const bannerSocialIcons={"max":"<svg xmlns=\"http://www.w3.org/2000/svg\" class=\"banner-social-icon max-mark\" viewBox=\"0 0 720 720\" width=\"21\" height=\"21\" fill=\"currentColor\" aria-hidden=\"true\" focusable=\"false\"><path d=\"M350.4,9.6C141.8,20.5,4.1,184.1,12.8,390.4c3.8,90.3,40.1,168,48.7,253.7,2.2,22.2-4.2,49.6,21.4,59.3,31.5,11.9,79.8-8.1,106.2-26.4,9-6.1,17.6-13.2,24.2-22,27.3,18.1,53.2,35.6,85.7,43.4,143.1,34.3,299.9-44.2,369.6-170.3C799.6,291.2,622.5-4.6,350.4,9.6h0ZM269.4,504c-11.3,8.8-22.2,20.8-34.7,27.7-18.1,9.7-23.7-.4-30.5-16.4-21.4-50.9-24-137.6-11.5-190.9,16.8-72.5,72.9-136.3,150-143.1,78-6.9,150.4,32.7,183.1,104.2,72.4,159.1-112.9,316.2-256.4,218.6h0Z\"/></svg>","ok":"<svg xmlns=\"http://www.w3.org/2000/svg\" class=\"banner-social-icon ok-mark\" viewBox=\"0 0 1258.2 2174.7\" width=\"21\" height=\"21\" fill=\"currentColor\" aria-hidden=\"true\" focusable=\"false\"><path d=\"M629.9,1122.4c310-0.1,561.1-251.5,561-561.4c-0.1-310-251.5-561.1-561.4-561S68.4,251.5,68.5,561.4  C68.9,871.2,320.1,1122.2,629.9,1122.4 M629.9,329c128.4,0,232.5,104.1,232.5,232.5S758.3,793.9,629.9,793.9  S397.4,689.8,397.4,561.4C397.6,433.1,501.6,329.1,629.9,329L629.9,329z M856.8,1580.3c115.5-26.2,225.7-71.9,326-135  c76.4-49.3,98.4-151.1,49.1-227.5c-48.5-75.2-148.3-97.9-224.5-51c-231.1,144.5-524.5,144.5-755.6,0c-76.7-48.1-178-25.1-226.3,51.5  c-48.5,76.7-25.7,178.3,51.1,226.8c0.1,0,0.2,0.1,0.2,0.1c100.2,63,210.4,108.7,325.8,135L88.8,1894c-62.5,66-59.6,170.2,6.5,232.7  c63.5,60,162.7,60,226.2,0l308.2-308.4l308.4,308.4c64.2,64.1,168.1,64.1,232.3,0c64.1-64.2,64.1-168.1,0-232.3L856.8,1580.3z\"/></svg>"};
  const socialButtons=(onBanner=false)=>`<div class="social-buttons"><a class="button primary max-trigger" href="https://max.ru/u/f9LHodD0cOKaOMjvuTLBEVfH1lGb5cDNrkHvBByFGdCg5YCWQJgUBWmQQRM" target="_blank" rel="noopener noreferrer">${onBanner?bannerSocialIcons.max:"<img class=\"max-logo\" src=\"./assets/max-logo-green.svg?v=b1399a3d11d3\" alt=\"\">"}Написать в MAX</a><a class="button secondary" href="https://ok.ru/profile/211714658759" target="_blank" rel="noopener noreferrer">${onBanner?bannerSocialIcons.ok:icon('odnoklassniki-green')}Одноклассники</a></div>`;
  const categoryCard=c=>`<a class="category-card" href="./catalog.html?category=${c.id}"><div class="category-photo"><img src="./assets/category-covers/${c.id}.webp" alt="${c.short}" width="800" height="800" loading="lazy"><span class="category-overlay"><span class="category-view">Смотреть</span></span></div><div class="category-caption"><h3>${c.id==='other'?'Другие цветы':c.name}</h3></div></a>`;
  const productCard=p=>`<article class="product-card"><div class="product-photo"><button class="product-open" data-product="${p.id}" aria-label="Подробнее: ${safe(p.name)}"><img src="./assets/${p.image}.webp" alt="${safe(p.name)}" width="600" height="600" loading="lazy"></button><button class="favorite-button ${saved.has(p.id)?'is-saved':''}" data-favorite="${p.id}" aria-label="${saved.has(p.id)?'Убрать из избранного':'Добавить в избранное'}: ${safe(p.name)}" aria-pressed="${saved.has(p.id)}">${icon(saved.has(p.id)?'ph-heart-fill':'ph-heart')}</button></div><span class="sku">Артикул ${p.sku?safe(p.sku):'не указан'}</span><h3><button class="product-name" data-product="${p.id}">${safe(p.name)}</button></h3><strong class="price">${priceLabel(p)}</strong></article>`;
  const main=$('#main');
  function home(){
    document.title='Цветы Надежды — вегетативные цветы и рассада в Назарово';
    main.innerHTML=`<section class="hero shell"><div class="hero-copy"><span class="eyebrow">Коллекция нового сезона</span><h1>Вегетативные<br>петунии</h1><p>Цветы, в которые влюбляются.<br>Выберите свои оттенки для нового сезона.</p><a class="button primary" href="./catalog.html?category=petunia">Смотреть в каталоге</a></div><div class="hero-image"><img src="./assets/hero-petunia-enhanced.webp" srcset="./assets/hero-petunia-enhanced-mobile.webp 900w, ./assets/hero-petunia-enhanced.webp 2294w" sizes="(max-width: 700px) calc(100vw - 36px), (max-width: 1400px) calc(100vw - 80px), 1320px" alt="Петунии из коллекции Надежды" width="2294" height="2742" fetchpriority="high"></div></section>
    <section class="section shell" id="catalog"><div class="section-heading"><div><h2>Найдите свой цветок</h2><p>Для сада, балкона и маленькой радости каждый день.</p></div><span class="section-meta">${categories.length} категорий</span></div><div class="category-grid">${categories.map(categoryCard).join('')}</div></section>
    <section class="about shell section" id="about"><div class="about-photo"><img src="./assets/about-nadezhda-flowers.webp" alt="Цветы из коллекции Надежды" loading="lazy" width="1079" height="1080"></div><div class="about-copy"><span class="eyebrow">Давайте знакомиться</span><h2>Я Надежда.<br>И это мой цветочный мир.</h2><p>Моё увлечение цветами уже 8 лет растёт вместе с моей коллекцией — сегодня в ней более 300 растений. Я выращиваю вегетативные цветы из европейских черенков, внимательно ухаживаю за ними и каждый сезон пополняю ассортимент.</p><p>Здесь можно выбрать укоренённые черенки, рассаду и растения разного размера. Принимаю заказы круглый год и предлагаю цветы из наличия.</p><p>За каждым растением — мой опыт и дело, которое я люблю.</p></div></section>
    <section class="delivery section" id="delivery"><div class="shell"><div class="section-heading"><div><h2>Ближе, чем кажется</h2><p>Доставка и самовывоз</p></div></div><p class="delivery-intro">Мы осуществляем доставку по всему <strong>Красноярскому краю и Республике Хакасия</strong>, чтобы вы могли получить свой заказ максимально удобно.</p><div class="delivery-grid"><div class="delivery-option"><span class="delivery-icon">${icon('ph-truck')}</span><div><h3>Доставка</h3><p>Доставляем заказы в города и населённые пункты Красноярского края и Хакасии. Сроки и стоимость доставки рассчитываются индивидуально в зависимости от вашего местоположения.</p></div></div><div class="delivery-option"><span class="delivery-icon">${icon('ph-map-pin')}</span><div><h3>Самовывоз из Назарово</h3><p>Вы также можете самостоятельно забрать свой заказ в городе <strong>Назарово</strong>. Мы всегда рады самовывозу — просто согласуйте с нами удобное время получения.</p></div></div></div><div class="delivery-cta"><div><h3>Хотите оформить заказ или узнать стоимость доставки?</h3><p>Свяжитесь с нами прямо сейчас! Мы рассчитаем стоимость доставки до вашего населённого пункта, ответим на все вопросы и поможем выбрать самый удобный способ получения заказа.</p></div>${socialButtons()}</div></div></section>
    <section class="contacts section shell" id="contacts"><div><span class="eyebrow">Всегда на связи</span><h2>Поговорим<br>о ваших цветах?</h2><p>Скопируйте список из <a href="./favorites.html">избранного</a> и отправьте его в личные сообщения в MAX или Одноклассниках для обсуждения деталей заказа.</p>${socialButtons()}</div><figure class="contact-map"><div class="contact-map-frame"><iframe title="Карта города Назарово — OpenStreetMap" src="https://www.openstreetmap.org/export/embed.html?bbox=90.325%2C55.98%2C90.51%2C56.045&amp;layer=mapnik&amp;marker=56.011593%2C90.418503" width="560" height="360" loading="lazy" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe></div><figcaption><span>г. Назарово, Красноярский край</span><a href="https://www.openstreetmap.org/?mlat=56.011593&amp;mlon=90.418503#map=12/56.011593/90.418503" target="_blank" rel="noopener noreferrer">Открыть карту</a></figcaption></figure></section>`;
  }
  function catalog(){
    const id=new URLSearchParams(location.search).get('category')||'petunia';
    const cat=categories.find(c=>c.id===id);
    if(!cat){main.innerHTML=`<section class="shell section empty"><h1>Категория не найдена</h1><a class="button primary" href="./index.html#catalog">Перейти в каталог</a></section>`;return;}
    document.title=cat.name+' | Цветы Надежды';
    main.innerHTML=`<section class="shell catalog-page"><nav class="breadcrumbs" aria-label="Хлебные крошки"><a href="./index.html">Главная</a><span>/</span><a href="./index.html#catalog">Каталог</a><span>/</span><span>${cat.short}</span></nav><h1>${cat.name}</h1><p class="catalog-description">${cat.desc}</p><nav class="category-tabs" aria-label="Категории растений">${categories.map(c=>`<a href="./catalog.html?category=${c.id}" ${c.id===id?'aria-current="page"':''}>${c.short}</a>`).join('')}</nav><div class="catalog-toolbar"><div class="catalog-controls"><label class="search-field">${icon('ph-magnifying-glass')}<input id="search" type="search" placeholder="Название или артикул" aria-label="Поиск по названию или артикулу"></label><details class="sort-control" id="sort"><summary aria-haspopup="menu" aria-controls="sort-options" aria-expanded="false"><span class="visually-hidden">Сортировка: </span><span class="sort-value">По умолчанию</span>${icon('ph-arrow-right')}</summary><div class="sort-options" id="sort-options" role="menu" aria-label="Сортировка товаров">${[['default','По умолчанию'],['low','Сначала дешевле'],['high','Сначала дороже'],['name','По названию']].map(([value,label])=>`<button type="button" role="menuitemradio" tabindex="-1" aria-checked="${value==='default'}" data-sort="${value}">${label}</button>`).join('')}</div></details></div><span id="results-count" aria-live="polite" aria-atomic="true"></span></div><div class="product-grid" id="products"></div><div class="catalog-order"><div><h2>Нашли свой цветок?</h2><p>Добавьте растения в избранное и напишите мне для заказа. Помогу с выбором и расскажу о наличии.</p></div>${socialButtons(true)}</div></section>`;
    const sortMenu=$('#sort'),sortToggle=$('summary',sortMenu);let sort='default';
    const render=()=>{const q=$('#search').value.toLocaleLowerCase('ru-RU').trim();let list=products.filter(p=>p.category===id&&`${p.name} ${p.sku||''}`.toLocaleLowerCase('ru-RU').includes(q));if(sort==='low')list.sort((a,b)=>(a.price??Infinity)-(b.price??Infinity));if(sort==='high')list.sort((a,b)=>(b.price??-Infinity)-(a.price??-Infinity));if(sort==='name')list.sort((a,b)=>a.name.localeCompare(b.name,'ru'));$('#products').innerHTML=list.length?list.map(productCard).join(''):`<div class="empty search-empty">${products.some(p=>p.category===id)?'<h2>Ничего не нашлось</h2><p>Попробуйте другое название или артикул.</p><button class="button secondary" id="reset-search">Сбросить поиск</button>':'<h2>Здесь скоро появятся цветы</h2><p>Карточки этой категории ещё не добавлены.<br>Напишите Надежде, чтобы узнать о поступлении.</p><a class="button primary max-trigger" href="https://max.ru/u/f9LHodD0cOKaOMjvuTLBEVfH1lGb5cDNrkHvBByFGdCg5YCWQJgUBWmQQRM" target="_blank" rel="noopener noreferrer">Узнать о поступлении</a>'}</div>`;$('#results-count').textContent=`Найдено: ${list.length}`;};
    $('#search').addEventListener('input',render);
    sortMenu.addEventListener('toggle',()=>{sortToggle.setAttribute('aria-expanded',String(sortMenu.open));if(sortMenu.open&&document.activeElement===sortToggle)sortMenu.querySelector('[aria-checked=true]').focus();});
    sortMenu.addEventListener('focusout',e=>{if(e.relatedTarget&&!sortMenu.contains(e.relatedTarget))sortMenu.open=false;});
    sortMenu.addEventListener('click',e=>{
      const option=e.target.closest('[data-sort]');if(!option)return;
      sort=option.dataset.sort;
      sortMenu.querySelectorAll('[data-sort]').forEach(b=>b.setAttribute('aria-checked',String(b===option)));
      $('.sort-value',sortMenu).textContent=option.textContent;
      sortMenu.open=false;sortToggle.focus();render();
    });
    sortMenu.addEventListener('keydown',e=>{
      if(e.key==='Escape'){e.preventDefault();e.stopPropagation();sortMenu.open=false;sortToggle.focus();return;}
      if(!['ArrowDown','ArrowUp','Home','End'].includes(e.key))return;
      e.preventDefault();const wasOpen=sortMenu.open;sortMenu.open=true;
      const options=[...sortMenu.querySelectorAll('[data-sort]')];
      const current=options.indexOf(document.activeElement);
      const next=e.key==='Home'?0:e.key==='End'?options.length-1:(!wasOpen||current<0)?options.findIndex(b=>b.getAttribute('aria-checked')==='true'):(current+(e.key==='ArrowDown'?1:-1)+options.length)%options.length;
      options[Math.max(0,next)].focus();
    });
    document.addEventListener('click',e=>{if(!sortMenu.contains(e.target))sortMenu.open=false;});
    render();
    main.addEventListener('click',e=>{if(e.target.closest('#reset-search')){$('#search').value='';render();}});
  }
  function favorites(){
    document.title='Избранное | Цветы Надежды';
    const list=products.filter(p=>saved.has(p.id));
    main.innerHTML=`<section class="shell catalog-page"><nav class="breadcrumbs" aria-label="Хлебные крошки"><a href="./index.html">Главная</a><span>/</span><span>Избранное</span></nav><div class="section-heading favorites-heading"><div><h1>Ваш цветочный выбор</h1><p>Здесь живут растения, которые вам понравились. <span class="favorites-count">${list.length} ${plural(list.length)}</span></p></div>${list.length?`<button class="button primary copy-list">${icon('ph-copy')}Скопировать</button>`:''}</div>${list.length?`<div class="product-grid">${list.map(productCard).join('')}</div><section class="favorites-summary" aria-labelledby="order-guide-title"><h2 id="order-guide-title">Как отправить свой выбор</h2><p class="order-guide-intro">Три простых шага, чтобы обсудить растения с Надеждой.</p><ol class="order-steps"><li class="order-step"><span class="step-number" aria-hidden="true">01</span><h3>Добавьте в избранное</h3><p>Нажимайте на сердечко у понравившихся растений. Они появятся на этой странице.</p></li><li class="order-step"><span class="step-number" aria-hidden="true">02</span><h3>Скопируйте список</h3><p>Нажмите кнопку ниже, чтобы скопировать весь список с названиями и артикулами.</p><button class="button primary copy-list">${icon('ph-copy')}Скопировать</button></li><li class="order-step"><span class="step-number" aria-hidden="true">03</span><h3>Отправьте сообщение</h3><p>Выберите MAX или Одноклассники под схемой. Вставьте список в личное сообщение и отправьте Надежде.</p></li></ol></section><div class="catalog-order"><div><h2>Отправьте список Надежде</h2><p>Вставьте скопированный список в личное сообщение в MAX или Одноклассниках. Обсудим наличие, размеры растений и цены.</p></div>${socialButtons(true)}</div>`:`<div class="empty">${icon('ph-heart')}<h2>Здесь расцветёт ваш выбор</h2><p>Нажимайте на сердечко у понравившихся растений.<br>Они сохранятся здесь, даже если вы закроете сайт.</p><a class="button primary" href="./index.html#catalog">Выбрать цветы ${icon('ph-arrow-right')}</a></div>`}</section>`;
  }
  function plural(n){return n%10===1&&n%100!==11?'растение':n%10>=2&&n%10<=4&&(n%100<12||n%100>14)?'растения':'растений';}
  function updateCount(){$('.favorites-link>img').src=`./assets/ph-heart${saved.size?'-fill':''}.svg?v=b1399a3d11d3`;document.querySelectorAll('.favorite-count').forEach(el=>{el.textContent=saved.size;el.hidden=!saved.size;});$('.favorites-link').setAttribute('aria-label',`Избранное, ${saved.size} ${plural(saved.size)}`);}
  let toastTimer;function toast(text){const el=$('.toast');el.textContent=text;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),3000);}
  async function copy(text,success){try{await navigator.clipboard.writeText(text);toast(success);}catch{const dialog=document.createElement('dialog');dialog.className='copy-dialog';dialog.innerHTML=`<h2>Скопируйте текст</h2><textarea aria-label="Текст для копирования" readonly></textarea><button class="button primary">Готово</button>`;document.body.append(dialog);$('textarea',dialog).value=text;$('button',dialog).onclick=()=>dialog.close();dialog.addEventListener('close',()=>dialog.remove());dialog.showModal();$('textarea',dialog).select();}}
  function openProduct(id){const p=products.find(p=>p.id===id);if(!p)return;const description=productDescription(p);const dialog=document.createElement('dialog');dialog.className='product-dialog'+(p.preserveSourceDescription?' source-photo-dialog':'');dialog.dataset.productId=p.id;dialog.setAttribute('aria-labelledby','product-title');dialog.innerHTML=`<button class="icon-button dialog-close" aria-label="Закрыть">${icon('ph-x')}</button><div class="detail-gallery"><img class="detail-photo" src="./assets/${p.image}.webp" alt="${safe(p.name)}" width="600" height="600">${p.images.length>1?`<div class="detail-thumbs">${p.images.map((image,i)=>`<button data-detail-image="${image}" aria-label="Фото ${i+1}" aria-pressed="${i===0}"><img src="./assets/${image}.webp" alt="Фото ${i+1}"></button>`).join('')}</div>`:''}</div><div class="detail-copy"><span class="sku">Артикул ${p.sku?safe(p.sku):'не указан'}</span><h2 id="product-title">${safe(p.name)}</h2>${description?`<p class="product-description">${safe(description)}</p>`:''}<strong class="price ${p.price===null?'price-on-request':''}">${priceLabel(p)}</strong><p class="sample-note">${stockNote}</p><button class="button secondary" data-favorite="${p.id}" aria-pressed="${saved.has(p.id)}">${icon(saved.has(p.id)?'ph-heart-fill':'ph-heart')}<span>${saved.has(p.id)?'В избранном':'В избранное'}</span></button><a class="button primary max-trigger" href="https://max.ru/u/f9LHodD0cOKaOMjvuTLBEVfH1lGb5cDNrkHvBByFGdCg5YCWQJgUBWmQQRM" target="_blank" rel="noopener noreferrer">Уточнить в MAX</a></div>`;document.body.append(dialog);$('.dialog-close',dialog).onclick=()=>dialog.close();dialog.addEventListener('close',()=>dialog.remove());dialog.addEventListener('click',e=>{if(e.target===dialog&&outsideDialog(e,dialog))dialog.close();});dialog.showModal();}
  function outsideDialog(e,d){const r=d.getBoundingClientRect();return e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom;}
  const page=location.pathname.split('/').pop();
  if(page==='catalog.html')catalog();else if(page==='favorites.html')favorites();else home();
  document.addEventListener('click',e=>{
    const thumb=e.target.closest('[data-detail-image]');if(thumb){const d=thumb.closest('dialog');$('.detail-photo',d).src='./assets/'+thumb.dataset.detailImage+'.webp';const p=products.find(p=>p.id===d.dataset.productId),caption=p?.sourcePhotos?.find(photo=>photo.image===thumb.dataset.detailImage)?.description;if(caption!==undefined&&$('.product-description',d))$('.product-description',d).textContent=productDescription({...p,description:caption});d.querySelectorAll('[data-detail-image]').forEach(b=>b.setAttribute('aria-pressed',String(b===thumb)));return;}
    const fav=e.target.closest('[data-favorite]');
    if(fav){const id=fav.dataset.favorite; saved.has(id)?saved.delete(id):saved.add(id);try{localStorage.setItem(key,JSON.stringify([...saved]));}catch{toast('Выбор сохранён только на время этого просмотра');}updateCount();document.querySelectorAll(`[data-favorite="${id}"]`).forEach(b=>{b.classList.toggle('is-saved',saved.has(id));b.setAttribute('aria-pressed',saved.has(id));const p=products.find(x=>x.id===id);b.setAttribute('aria-label',`${saved.has(id)?'Убрать из избранного':'Добавить в избранное'}: ${safe(p.name)}`);$('img.icon',b).src=`./assets/ph-heart${saved.has(id)?'-fill':''}.svg?v=b1399a3d11d3`;if($('span',b))$('span',b).textContent=saved.has(id)?'В избранном':'В избранное';});if(page==='favorites.html'){const next=products.filter(p=>saved.has(p.id));if(!next.length){document.querySelectorAll('.product-dialog').forEach(d=>d.close());favorites();}else{favorites();}}toast(saved.has(id)?'Растение добавлено в избранное':'Растение удалено из избранного');return;}
    if(e.target.closest('.copy-list')){const list=products.filter(p=>saved.has(p.id));copy(`Здравствуйте, Надежда! Интересуют растения:\n\n${list.map(p=>`Арт. ${p.sku||'не указан'}: ${p.name} (${p.price===null?'цена по запросу':p.price+' руб.'})`).join('\n')}\n\nПодскажите, пожалуйста, наличие и актуальную стоимость.`,'Список скопирован. Вставьте его в личное сообщение в MAX или Одноклассниках.');return;}
    const open=e.target.closest('[data-product]');if(open)openProduct(open.dataset.product);
  });
  $('.menu-toggle').addEventListener('click',()=>{const menu=$('#mobile-menu');menu.hidden=!menu.hidden;$('.menu-toggle').setAttribute('aria-expanded',String(!menu.hidden));$('.menu-toggle').setAttribute('aria-label',menu.hidden?'Открыть меню':'Закрыть меню');});
  document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('#mobile-menu').hidden=true;$('.menu-toggle').setAttribute('aria-expanded','false');}});
  $('#mobile-menu').addEventListener('click',e=>{if(e.target.closest('a,button')){$('#mobile-menu').hidden=true;$('.menu-toggle').setAttribute('aria-expanded','false');}});
  let choice;try{choice=localStorage.getItem('nadezhda-theme');}catch{}
  function setTheme(value){document.documentElement.dataset.theme=value;const button=$('.theme-toggle');$('img',button).src=`./assets/ph-${value==='dark'?'sun':'moon'}.svg?v=b1399a3d11d3`;button.setAttribute('aria-label',value==='dark'?'Включить светлую тему':'Включить тёмную тему');}
  setTheme(choice||'light');
  $('.theme-toggle').addEventListener('click',()=>{choice=document.documentElement.dataset.theme==='dark'?'light':'dark';setTheme(choice);try{localStorage.setItem('nadezhda-theme',choice);}catch{}});

  window.addEventListener('storage',e=>{if(e.key===key){try{const raw=JSON.parse(e.newValue||'[]');saved=new Set(Array.isArray(raw)?raw.filter(id=>products.some(p=>p.id===id)):[]);updateCount();if(page==='favorites.html')favorites();else document.querySelectorAll('[data-favorite]').forEach(b=>{b.classList.toggle('is-saved',saved.has(b.dataset.favorite));b.setAttribute('aria-pressed',saved.has(b.dataset.favorite));$('img.icon',b).src=`./assets/ph-heart${saved.has(b.dataset.favorite)?'-fill':''}.svg?v=b1399a3d11d3`;const label=$('span',b);if(label)label.textContent=saved.has(b.dataset.favorite)?'В избранном':'В избранное';});}catch{}}});
  updateCount();
  if(location.hash)requestAnimationFrame(()=>$(location.hash)?.scrollIntoView());
})();
